@sig trait AccessActionEligibility_Api {
  def id: Art.BridgeId
  def admission_decision_Id : Art.PortId
  def access_frame_Id : Art.PortId
  def access_proposal_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var access_proposal: Docking_Access_Supervisor.AccessProposal = $

  def put_access_proposal(value : Docking_Access_Supervisor.AccessProposal) : Unit = {
    Contract(
      Modifies(access_proposal),
      Ensures(
        access_proposal == value
      )
    )
    Spec {
      access_proposal = value
    }

    Art.putValue(access_proposal_Id, Docking_Access_Supervisor.AccessProposal_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

